# =====================================================================
# Окна сроков: один общий срок на несколько подряд идущих шагов
# (label, первый шаг, последний шаг, источник) — номера шагов внутри процесса
# =====================================================================
_SPANS = {
 "ОС1":   [("Общий срок приёма клиента — 5 р.д.", 1, 14, "Н", {"exclude": [10], "cover": False, "rewrite": False}),
           ("1 р.д. (день 1)", 1, 4, "Н"), ("1 р.д. (день 2)", 5, 6, "Н"), ("1 р.д. (день 3: ответ клиента)", 7, 7, "Н"),
           ("1 р.д. (день 4)", 8, 11, "Н", {"exclude": [10]}), ("1 р.д. (день 5)", 12, 14, "Н")],
 "ОС3":   [("2 р.д.", 1, 3, "Н")],
 "ПС5":   [("2 р.д.", 1, 3, "Н")],
 "ОЛ2.1": [("3 р.д.", 2, 3, "Пр"), ("до срока сдачи −3 р.д.", 7, 9, "Н"), ("по законным срокам", 11, 12, "З")],
 "ОЛ2.2": [("3 р.д. на ответ источника", 1, 3, "Пр"), ("по 209-ФЗ и приказу №74/114/пр", 7, 8, "З")],
}
for _p in P:
    for _s in _p["steps"]:
        if _s["dl"] == "По срокам П1": _s["dl"] = "По срокам ОС1"
    _sp = []
    _ids = [s["id"] for s in _p["steps"]]
    for _t in _SPANS.get(_p["id"], []):
        _lab, _a, _b, _src = _t[:4]; _o = _t[4] if len(_t) > 4 else {}
        _ia, _ib = f'{_p["id"]}.{_a}', f'{_p["id"]}.{_b}'
        _excl = [f'{_p["id"]}.{x}' for x in _o.get("exclude", [])]
        _rng = [s for s in _p["steps"][_ids.index(_ia):_ids.index(_ib) + 1] if s["id"] not in _excl]
        if _o.get("rewrite", True):
            for _s in _rng:
                if _s["kind"] == "decision": continue
                _s["dl"] = f"{_lab} — общий срок на шаги {_ia}–{_ib}" if _a != _b else _lab
                _s["src"] = _src
        _sp.append((_lab, _ia, _ib, _src, dict(_o, exclude=_excl)))
    _p["spans"] = _sp

def _deadline_windows():
    rows = []
    for p in P:
        for t in p.get("spans", []):
            lab, a, b, src = t[0], t[1], t[2], t[3]
            rows.append((p["id"], p["name"], a, b, lab, src))
    return rows
DEADLINE_WINDOWS = _deadline_windows()
